create or replace function public.post_gateway_fee_financial_journal() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare fee numeric; begin fee:=coalesce(new.provider_fee,0); if fee > 0 and (tg_op='INSERT' or old.provider_fee is distinct from new.provider_fee) then perform public.post_gateway_financial_journal(new.user_id,new.transaction_id,(select gateway_id from public.reconciliation_runs where id=new.run_id),'fee','reconciliation_fee:'||new.id::text,(select currency from public.gateway_transactions where id=new.transaction_id),jsonb_build_array(jsonb_build_object('account_code','gateway_fees','direction','debit','amount',fee),jsonb_build_object('account_code','gateway_receivable','direction','credit','amount',fee)),jsonb_build_object('source','reconciliation_fee','reconciliation_item_id',new.id,'run_id',new.run_id,'external_transaction_id',new.external_transaction_id)); end if; return new; end $$; drop trigger if exists trg_gateway_fee_financial_posting on public.reconciliation_items; create trigger trg_gateway_fee_financial_posting after insert or update of provider_fee on public.reconciliation_items for each row execute function public.post_gateway_fee_financial_journal(); revoke execute on function public.post_gateway_fee_financial_journal() from public,anon,authenticated;